import{_ as a,o as s,c as e,a2 as l}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"⚙️ 双核心规则引擎","description":"","frontmatter":{},"headers":[],"relativePath":"iot/rule-engine.md","filePath":"iot/rule-engine.md"}'),i={name:"iot/rule-engine.md"};function t(o,n,p,r,c,d){return s(),e("div",null,[...n[0]||(n[0]=[l(`<h1 id="⚙️-双核心规则引擎" tabindex="-1">⚙️ 双核心规则引擎 <a class="header-anchor" href="#⚙️-双核心规则引擎" aria-label="Permalink to &quot;⚙️ 双核心规则引擎&quot;">​</a></h1><p>MzMedia 内置了<strong>数据流转规则引擎</strong>与<strong>场景联动规则引擎</strong>两大中枢，构筑了高吞吐、敏捷自愈的自动化体系。</p><hr><h2 id="_1-架构总览" tabindex="-1">1. 架构总览 <a class="header-anchor" href="#_1-架构总览" aria-label="Permalink to &quot;1. 架构总览&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                           ┌───────────────────────────┐</span></span>
<span class="line"><span>                           │    设备上报属性 / 事件    │</span></span>
<span class="line"><span>                           └─────────────┬─────────────┘</span></span>
<span class="line"><span>                                         ▼</span></span>
<span class="line"><span>                           ┌───────────────────────────┐</span></span>
<span class="line"><span>                           │     规则引擎过滤与评估    │</span></span>
<span class="line"><span>                           │  (SpEL / JSONPath 表达式) │</span></span>
<span class="line"><span>                           └──────┬─────────────┬──────┘</span></span>
<span class="line"><span>             命中数据分发规则     │             │    命中场景联动规则</span></span>
<span class="line"><span>        ┌─────────────────────────┘             └─────────────────────────┐</span></span>
<span class="line"><span>        ▼                                                                 ▼</span></span>
<span class="line"><span>┌──────────────────────────────┐                         ┌──────────────────────────────┐</span></span>
<span class="line"><span>│  9 种数据分发目的地 (Sink)   │                         │  TCA 场景联动执行动作        │</span></span>
<span class="line"><span>├──────────────────────────────┤                         ├──────────────────────────────┤</span></span>
<span class="line"><span>│ · TDengine（时序大数据入库） │                         │ · 远程设置设备属性 / 调用服务│</span></span>
<span class="line"><span>│ · MySQL / PostgreSQL（存盘） │                         │ · 联动摄像头旋转预置位并抓拍 │</span></span>
<span class="line"><span>│ · Redis Stream（缓存与分发） │                         │ · 触发 Flowable 运维报修工单 │</span></span>
<span class="line"><span>│ · RocketMQ / Kafka / RabbitMQ│                         │ · 联动第三方 Webhook / 短信  │</span></span>
<span class="line"><span>│ · MQTT Broker / Webhook 推送 │                         │ · 自动生成并恢复告警记录     │</span></span>
<span class="line"><span>└──────────────────────────────┘                         └──────────────────────────────┘</span></span></code></pre></div><hr><h2 id="_2-数据分发引擎-iotdatarule" tabindex="-1">2. 数据分发引擎 (<code>IotDataRule</code>) <a class="header-anchor" href="#_2-数据分发引擎-iotdatarule" aria-label="Permalink to &quot;2. 数据分发引擎 (\`IotDataRule\`)&quot;">​</a></h2><ul><li><strong>条件过滤</strong>：支持基于 SpEL（Spring Expression Language）进行灵活表达式编写，如：<div class="language-spel vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">spel</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#payload.temperature &gt; 50.0 &amp;&amp; #payload.deviceType == &#39;HVAC&#39;</span></span></code></pre></div></li><li><strong>9 种 Sink 输出目的地</strong>： <ol><li><strong>TDengine</strong>：写入时序超级表，承载每秒数万点位的高并发遥测数据；</li><li><strong>MySQL / PostgreSQL</strong>：关系数据库直接存盘，适合资产基础属性留痕；</li><li><strong>Redis Stream</strong>：低延迟内存消息队列，供前端大屏实时推流；</li><li><strong>Kafka / RocketMQ / RabbitMQ</strong>：对接企业级大数据计算中台（Flink/Spark）；</li><li><strong>HTTP Webhook</strong>：实时推送至企业钉钉/飞书机器人或上级监管平台；</li><li><strong>MQTT Broker</strong>：重新发布至指定 Topic，驱动边缘节点联锁控制；</li><li><strong>TCP / WebSocket</strong>：直接转发至指定第三方客户端连接。</li></ol></li></ul><hr><h2 id="_3-场景联动引擎-iotscenerule-tca-架构" tabindex="-1">3. 场景联动引擎 (<code>IotSceneRule</code> - TCA 架构) <a class="header-anchor" href="#_3-场景联动引擎-iotscenerule-tca-架构" aria-label="Permalink to &quot;3. 场景联动引擎 (\`IotSceneRule\` - TCA 架构)&quot;">​</a></h2><ul><li><strong>触发器 (Trigger)</strong>： <ul><li>属性上报：某个传感器上报数值；</li><li>设备状态：设备由在线突变离线；</li><li>定时调度：每天晚上 22:00 自动触发夜间安防模式。</li></ul></li><li><strong>条件评估 (Condition)</strong>： <ul><li>属性多条件与/或比对；</li><li>生效时间段过滤（如“工作日 08:30-17:30”）。</li></ul></li><li><strong>执行动作 (Action)</strong>： <ul><li><strong>★ 视频联动 (<code>IotMediaSceneRuleAction</code>)</strong>：向系统事件总线发布 <code>IotMediaLinkageEvent</code>，命令指定国标摄像头转向故障预置位（<code>0x81</code>）并开始云端录像；</li><li><strong>工单派发</strong>：自动触发 Flowable 运维报修审批流；</li><li><strong>反向控制</strong>：向就近的排风扇或切断阀发送 Modbus 下行写寄存器命令。</li></ul></li></ul>`,11)])])}const h=a(i,[["render",t]]);export{u as __pageData,h as default};
